import{_ as r,a0 as i,w as a,s as m,ao as p,I as s,a1 as n,A as l,x as t}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const g=JSON.parse('{"title":"怎样把坏的MySQL查询找到并杀死？ | LCTT x X-CMD","titleTemplate":false,"description":"怎样把坏的MySQL查询找到并杀死？ | LCTT (201407) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"怎样把坏的MySQL查询找到并杀死？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"怎样把坏的MySQL查询找到并杀死？ | LCTT (201407) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201407/20140703 How to find and kill misbehaving MySQL queries","title":"怎样把坏的MySQL查询找到并杀死？","tag":"201407","desc":""},"relativePath":"201407/20140703 How to find and kill misbehaving MySQL queries.md","filePath":"[post].md"}'),d={name:"201407/20140703 How to find and kill misbehaving MySQL queries.md"};function L(u,e,y,f,S,h){const o=i("Link");return a(),m("div",null,[e[12]||(e[12]=p(`<h1 id="怎样把坏的mysql查询找到并杀死" tabindex="-1">怎样把坏的MySQL查询找到并杀死？ <a class="header-anchor" href="#怎样把坏的mysql查询找到并杀死" aria-label="Permalink to “怎样把坏的MySQL查询找到并杀死？”">​</a></h1><p>有时，关系型相关数据库系统的复杂性会把你搞晕，不过幸运的是，使用MySQL工具来管理查询就就可以避免这些复杂性。 在本教程中，我将向你们展示 <strong>怎样去查找并杀掉任何非法的MySQL查询</strong>。</p><p>为了浏览当前正在运行的查询，登陆到MySQL终端，然后运行‘show processlist’命令:</p><pre><code>mysql&gt; show processlist; 

+--------+--------+-----------------+---------+---------+-------+-------+------------------+-----------+---------------+-----------+
| Id     | User   | Host            | db      | Command | Time  | State | Info             | Rows_sent | Rows_examined | Rows_read |
+--------+--------+-----------------+---------+---------+-------+-------+------------------+-----------+---------------+-----------+
|  78233 | root   | 127.0.0.1:37527 | mysql   | Sleep   | 16474 |       | NULL             |         6 |             6 |         6 |
|  84546 | root   | 127.0.0.1:48593 | mysql   | Sleep   | 13237 |       | NULL             |         2 |             2 |         2 |
| 107083 | root   | 127.0.0.1:56451 | mysql   | Sleep   | 15488 |       | NULL             |         1 |           121 |       121 |
| 131455 | root   | 127.0.0.1:48550 | NULL    | Query   |     0 | NULL  | show processlist |         0 |             0 |         0 |
+--------+--------+-----------------+---------+---------+-------+-------+------------------+-----------+---------------+-----------+
4 rows in set (0.03 sec)
</code></pre><p>首先你应该查看&#39;Time&#39;项，这里记录了进程执行 &quot;做其当做的事情&quot; 操作的秒数。‘command’项处于‘Sleep’ 状态的进程表示其正在等待接受查询，因此，它并没有消耗任何资源。对于其他任何进程而言，‘Time’超过一定的秒数表明出现问题。</p><p>在上面的例子中，唯一运行的查询是我们的‘show processlist’命令。让我们来看看如果我们有一个写的很烂的查询是怎么样的:</p><pre><code>mysql&gt; show processlist; 

+--------+--------+-----------------+-----------+---------+-------+--------------+----------------------------------+-----------+---------------+-----------+
| Id     | User   | Host            | db        | Command | Time  | State        | Info                             | Rows_sent | Rows_examined | Rows_read |
+--------+--------+-----------------+-----------+---------+-------+--------------+----------------------------------+-----------+---------------+-----------+
|  78233 | root   | 127.0.0.1:37527 | example   | Sleep   | 18046 |              | NULL                             |         6 |             6 |         6 |
|  84546 | root   | 127.0.0.1:48593 | example   | Sleep   | 14809 |              | NULL                             |         2 |             2 |         2 |
| 107083 | root   | 127.0.0.1:56451 | example   | Sleep   | 17060 |              | NULL                             |         1 |           121 |       121 |
| 132033 | root   | 127.0.0.1:54642 | example   | Query   |    27 | Sending data | select max(subtotal) from orders |         0 |             0 |         0 |
| 133933 | root   | 127.0.0.1:48679 | NULL      | Query   |     0 | NULL         | show processlist                 |         0 |             0 |         0 |
| 134122 | root   | 127.0.0.1:49264 | example   | Sleep   |     0 |              | NULL                             |         0 |             0 |         0 |
+--------+--------+-----------------+-----------+---------+-------+--------------+----------------------------------+-----------+---------------+-----------+
6 rows in set (0.00 sec)
</code></pre><p>啊哈！现在我们看到有一个查询运行了将近30秒。如果我们不想让它的进程继续运行，可以将它的&#39;Id&#39;传递给kill命令:</p><pre><code>mysql&gt; kill 132033;
Query OK, 0 rows affected (0.00 sec)
mysql&gt; 
</code></pre><p>(注意 由于我们没有改变任何数据，MySQL总是报告0行被影响。)</p><p>明智的使用kill命令能够清除积压的查询。然而，要记住的是，那不是一种永久的方法 - 如果这些查询来自你的程序，你需要去重写它们，或者将继续看到相同的问题不断出现。</p><h3 id="另请参阅" tabindex="-1">另请参阅 <a class="header-anchor" href="#另请参阅" aria-label="Permalink to “另请参阅”">​</a></h3><p>关于不同‘命令’的MySQL文档:</p>`,13)),s("ul",null,[s("li",null,[n(o,{href:"https://dev.mysql.com/doc/refman/5.7/en/thread-commands.html"},{default:l(()=>[...e[0]||(e[0]=[t("https://dev.mysql.com/doc/refman/5.7/en/thread-commands.html",-1)])]),_:1})])]),e[13]||(e[13]=s("hr",null,null,-1)),s("p",null,[e[2]||(e[2]=t("via: ",-1)),n(o,{href:"http://xmodulo.com/2014/07/find-kill-misbehaving-mysql-queries.html"},{default:l(()=>[...e[1]||(e[1]=[t("http://xmodulo.com/2014/07/find-kill-misbehaving-mysql-queries.html",-1)])]),_:1})]),s("p",null,[e[5]||(e[5]=t("译者：",-1)),n(o,{href:"https://github.com/hunanchenxingyu"},{default:l(()=>[...e[3]||(e[3]=[t("hunanchenxingyu",-1)])]),_:1}),e[6]||(e[6]=t(" 校对：",-1)),n(o,{href:"https://github.com/wxy"},{default:l(()=>[...e[4]||(e[4]=[t("wxy",-1)])]),_:1})]),s("p",null,[e[9]||(e[9]=t("本文由 ",-1)),n(o,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...e[7]||(e[7]=[t("LCTT",-1)])]),_:1}),e[10]||(e[10]=t(" 原创翻译，",-1)),n(o,{href:"http://linux.cn/"},{default:l(()=>[...e[8]||(e[8]=[t("Linux中国",-1)])]),_:1}),e[11]||(e[11]=t(" 荣誉推出",-1))])])}const w=r(d,[["render",L]]);export{g as __pageData,w as default};
